test_suite:
test('createReactive reflects initial values', () => {
  const state = createReactive({ x: 10 });
  expect(state.x).toBe(10);
});

test('createReactive reflects updated values', () => {
  const state = createReactive({ x: 10 });
  state.x = 20;
  expect(state.x).toBe(20);
});

test('computed returns correct initial value', () => {
  const state = createReactive({ a: 3, b: 4 });
  const sum = computed(() => state.a + state.b);
  expect(sum.value).toBe(7);
});

test('computed updates when dependency changes', () => {
  const state = createReactive({ n: 2 });
  const sq = computed(() => state.n * state.n);
  expect(sq.value).toBe(4);
  state.n = 5;
  expect(sq.value).toBe(25);
});

