test('computed does not re-run when unrelated prop changes', () => {
  const state = createReactive({ a: 1, b: 100 });
  let runs = 0;
  const c = computed(() => { runs++; return state.a; });
  c.value;
  state.b = 200;
  c.value;
  expect(runs).toBe(1);
});

solution:
let currentEffect = null;

export function createReactive(obj) {
  const deps = {};

  function track(key) {
    if (currentEffect) {
      if (!deps[key]) deps[key] = new Set();
      deps[key].add(currentEffect);
    }
  }

  function trigger(key) {
    if (deps[key]) deps[key].forEach(fn => fn());
  }

  return new Proxy(obj, {
    get(target, key) {
      track(key);
      return target[key];
    },
    set(target, key, value) {
      target[key] = value;
      trigger(key);
      return true;
    }
  });
}

export function computed(fn) {
  let cachedValue;
  let dirty = true;

  const effect = () => { dirty = true; };

  return {
    get value() {
      if (dirty) {
        const prev = currentEffect;
        currentEffect = effect;
        cachedValue = fn();
        currentEffect = prev;
        dirty = false;
      }
      return cachedValue;
    }
  };
}
